78	  protected volatile LockItem lock;
79	
80	  protected DynamoDBBasedLockProviderBase(final LockConfiguration lockConfiguration, final StorageConfiguration<?> conf, DynamoDbClient dynamoDB) {
81	    this.dynamoDbBasedLockConfig = new DynamoDbBasedLockConfig.Builder()
82	        .fromProperties(lockConfiguration.getConfig())
83	        .build();
84	    this.tableName = dynamoDbBasedLockConfig.getString(DynamoDbBasedLockConfig.DYNAMODB_LOCK_TABLE_NAME);
85	    long leaseDuration = dynamoDbBasedLockConfig.getInt(DynamoDbBasedLockConfig.LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY);
86	    dynamoDBPartitionKey = getDynamoDBPartitionKey(lockConfiguration);
87	    if (dynamoDB == null) {
88	      dynamoDB = getDynamoDBClient(dynamoDbBasedLockConfig);
89	    }
90	    // build the dynamoDb lock client
91	    this.client = new AmazonDynamoDBLockClient(
92	        AmazonDynamoDBLockClientOptions.builder(dynamoDB, tableName)
93	            .withTimeUnit(TimeUnit.MILLISECONDS)
94	            .withLeaseDuration(leaseDuration)
95	            .withHeartbeatPeriod(leaseDuration / 3)
96	            .withCreateHeartbeatBackgroundThread(true)
97	            .build());
98	
99	    if (!this.client.lockTableExists()) {
100	      createLockTableInDynamoDB(dynamoDB, tableName);
101	    }
102	  }
